import{_ as a,o as s,c as o,a3 as n}from"./chunks/framework.DdpBa4_E.js";const l="/ReadBooks/assets/975826_img_001.CygKtyoP.png",r="/ReadBooks/assets/975826_img_002.5ZBfYcuF.png",p="/ReadBooks/assets/975826_img_003.DBTZ7_uc.png",t="/ReadBooks/assets/975826_img_004.BoyWnkke.png",i="/ReadBooks/assets/975826_img_005.1seNwGo_.png",d="/ReadBooks/assets/975826_img_006.CkMP7o-d.png",c="/ReadBooks/assets/975826_img_007.Dl6s-v9Y.png",v=JSON.parse('{"title":"07｜安装画图工具：给 Claude Code 装上画图 Skill","description":"","frontmatter":{},"headers":[],"relativePath":"books/claude-code-legacy/07-安装画图工具-给-Claude-Code-装上画图-Skill.md","filePath":"books/claude-code-legacy/07-安装画图工具-给-Claude-Code-装上画图-Skill.md","lastUpdated":1794316978000}'),g={name:"books/claude-code-legacy/07-安装画图工具-给-Claude-Code-装上画图-Skill.md"};function u(m,e,h,b,k,C){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_07-安装画图工具-给-claude-code-装上画图-skill" tabindex="-1">07｜安装画图工具：给 Claude Code 装上画图 Skill <a class="header-anchor" href="#_07-安装画图工具-给-claude-code-装上画图-skill" aria-label="Permalink to &quot;07｜安装画图工具：给 Claude Code 装上画图 Skill&quot;">​</a></h1><p><strong>作者：Robert</strong></p><p>🎧 <strong>文章音频</strong>: [🎧 点击播放：_assets/975826.mp3]</p><blockquote><p>在讲怎么画之前，得先让 Claude Code 真的能画图。</p></blockquote><p>你好，我是 Robert。</p><p>上一讲的八步心法里，第 4 步是“画项目全景”。这一讲按理说应该开始画 Spring AI Alibaba Admin 的架构图了，但动笔之前我想先停一下，因为我意识到一件事：<strong>在讲怎么画之前，得先让 Claude Code 真的能画图</strong>。</p><p>你试过没有？打开 Claude Code，跟它说“帮我画一张项目架构图”，它大概率会给你一段 mermaid 源码，让你自己去 mermaid.live 或者别的地方渲染。</p><p><img src="'+l+`" alt="图片" loading="lazy"></p><p>这不是 Claude Code 的问题，是<strong>它出厂时没带画图能力</strong>，但给它装上很容易。装好之后，它能直接给你出 PNG、SVG、PDF，能在浏览器里实时预览。</p><p>学完这一讲，你会有两样东西：<strong>一个装好画图能力的 Claude Code</strong>，以及<strong>一张“什么场景用什么图”的心智地图</strong>。</p><h2 id="花一分钟认识-skill" tabindex="-1">花一分钟认识 SKILL <a class="header-anchor" href="#花一分钟认识-skill" aria-label="Permalink to &quot;花一分钟认识 SKILL&quot;">​</a></h2><p>讲画图之前，先花点时间讲 SKILL 是什么。Claude Code 启动时会做一件事：<strong>扫两个目录</strong>。一个是你的用户目录 <code>~/.claude/skills/</code>，另一个是项目根目录 <code>.claude/skills/</code>。扫到的每个 SKILL 会被加载进上下文，成为 Claude Code 的“知识库”。</p><p>**一个 SKILL 长什么样？**就是一个文件夹，里面一个 <code>SKILL.md</code> 文件，再可选地带一些 reference 文档或辅助脚本。SKILL.md 是关键，它告诉 Claude Code 这个 SKILL 干什么、什么时候用、用什么工具。Claude Code 看完就知道自己多了一项能力。</p><p>**怎么装？**一般两种方式。</p><ol><li>Plugin 方式：Claude Code 内置了 plugin marketplace 机制，在 Claude Code 里输入 <code>/plugin marketplace add 某个 github 仓库</code>，再 <code>/plugin install</code> 就好。这种装法自动处理依赖、自动配置 MCP server，最省事。</li><li>手动 clone：直接 <code>git clone</code> 到 <code>~/.claude/skills/</code> 或项目的 <code>.claude/skills/</code> 下，重启 Claude Code 就生效。这种方式更透明，适合你想看看 SKILL 里面是什么、想自己改改的场景。</li></ol><p>就这么简单。不是黑盒，是一个文件夹。<strong>哪里找好的 SKILL？</strong></p><ul><li>Anthropic 官方 plugin marketplace：在 Claude Code 里 <code>/plugin marketplace list</code> 能看到官方收录的。</li><li>GitHub 搜 claude-code skills 或 claude skill：社区项目很多。</li><li>第三方聚合站：比如 skillsdirectory.com、fastmcp.me 收录了大量可用 SKILL 和它们的安装命令。</li></ul><p>提醒一下：这一讲你装的是别人写好的 SKILL，就像你用 npm 装别人的 package。11 讲会讲怎么自己写 SKILL.md，把你项目里反复出现的模式沉淀下来给 Claude Code。消费者和生产者都会教，这一讲先做消费者。好了，SKILL 讲完，接下来看四类必备图。</p><h2 id="工具怎么选-安装-claude-mermaid" tabindex="-1">工具怎么选？安装 claude-mermaid <a class="header-anchor" href="#工具怎么选-安装-claude-mermaid" aria-label="Permalink to &quot;工具怎么选？安装 claude-mermaid&quot;">​</a></h2><p>工具层面，我推荐这样的配置：</p><ol><li><strong>mermaid</strong>：90% 的场景用它。Claude Code、Cursor、GitHub、Notion、VS Code 原生都支持，AI 生成 mermaid 代码的能力也最强。这一讲主讲 mermaid。</li><li><strong>plantuml</strong>：偶尔需要画更复杂的 UML 图（比如详细的类图、复杂的时序图带 frame 结构），plantuml 比 mermaid 表达力强。但语法稍重，AI 生成时容易出错。</li><li><strong>drawio（diagrams.net）</strong>：画“最终交付的架构图”时用。drawio 出来的图好看、正式、适合放到文档和汇报材料里。但不适合让 AI 快速生成，更适合你拿到 AI 的 mermaid 初稿后，用 drawio 精修。</li></ol><p><strong>我的日常流程是这样</strong>：用 mermaid 快速迭代、反复改、留在项目 <code>docs/</code> 里；最终要交付到外部（PPT、正式文档）的那一两张，用 drawio 精修。plantuml 用得少，偶尔做复杂时序图用一次。这一讲装的就是 mermaid 能力，plantuml 和 drawio 需要时再装，装法类似。</p><p>mermaid 能力现在有一个特别成熟的方案，叫 <strong>claude-mermaid</strong>（作者 veelenga）。它是一个 MCP Server + Plugin 一体的方案。<strong>装法有两步，少一步就用不了。</strong></p><ol><li>装 claude-mermaid 命令本身：</li></ol><div class="language-plain vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm install -g claude-mermaid</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这步装的是真正干渲染活的 Node 程序。没有它，后面的 Plugin 只是空壳。Node 版本需要 20 或更高，<code>node -v</code> 确认一下。</p><ol start="2"><li>在 Claude Code 里装 Plugin：</li></ol><div class="language-plain vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin marketplace add veelenga/claude-mermaid</span></span>
<span class="line"><span>/plugin install claude-mermaid@claude-mermaid</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这步装的是 Skill 定义和 MCP 配置。装完后，<strong>完全退出 Claude Code 再重新启动</strong>（不是 reload），让 MCP Server 起来。如果安装遇到问题，可以直接让 Claude Code 帮忙解决即可。</p><p><strong>验证</strong>：</p><p>装完你可以试一句：画个最简单的用户登录流程图，保存到当前目录。效果图如下：</p><p><img src="`+r+'" alt="图片" loading="lazy"></p><h2 id="了解老项目需要的四类必备图" tabindex="-1">了解老项目需要的四类必备图 <a class="header-anchor" href="#了解老项目需要的四类必备图" aria-label="Permalink to &quot;了解老项目需要的四类必备图&quot;">​</a></h2><p>如下图所示，老项目改造过程里会反复需要的图就那么四类。</p><p><img src="'+p+`" alt="图片" loading="lazy"></p><p><strong>第一类：架构图</strong></p><p>用方框和箭头展示系统的骨架。前端、后端、数据库、中间件、外部服务之间的关系。颗粒度粗，一张图把整个系统的样子说清楚。用在 08 讲画项目全景、10 讲 CLAUDE.md 的“项目架构”小节、13 讲编译运行时理清依赖、第四部分改造时判断影响范围。</p><p><strong>第二类：模块依赖图</strong></p><p>有向图，节点是项目里的模块或包，边是依赖关系。让你一眼看出，哪个模块是底层、哪个是上层、有没有循环依赖。用在 08 讲画模块依赖、后面任何时候你想知道“改这个模块会拖动谁”的时候。</p><p><strong>第三类：时序图</strong></p><p>用时间轴展示多个参与者之间的交互。用户 → 前端 → Controller → Service → DB，一次请求从上到下走一遍。用在09 讲梳理接口时画“一次 API 调用的完整生命周期”、复现 bug 时画“问题路径”、第四部分改造时对照“改造前 vs 改造后的调用链”。</p><p><strong>第四类：数据库 schema 图（ER 图）</strong></p><p>表和表之间的外键关系。主键、外键、关联方向一目了然。用在 09 讲梳理数据模型、改造涉及 DB 的任何时候、给接手同事讲数据关系的时候。</p><p>这四类图基本覆盖老项目改造的全部场景。还有一些图，比如状态图、类图、部署图，用到的概率低，等真碰到再说。</p><h2 id="四类图的画法-提示词-坑" tabindex="-1">四类图的画法：提示词 + 坑 <a class="header-anchor" href="#四类图的画法-提示词-坑" aria-label="Permalink to &quot;四类图的画法：提示词 + 坑&quot;">​</a></h2><h3 id="架构图" tabindex="-1">架构图 <a class="header-anchor" href="#架构图" aria-label="Permalink to &quot;架构图&quot;">​</a></h3><p>最常用的一类。用 mermaid 的 <code>graph TD</code>（从上往下）或 <code>graph LR</code>（从左往右）。下面的提示词我在Spring AI Alibaba Admin 项目的源码中尝试执行。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我画一张这个项目的架构图。前端、后端、数据库、外部服务分层画出来。</span></span>
<span class="line"><span>每个模块写名字加一句话职责。别画实现细节，服务级就够了。</span></span>
<span class="line"><span>保存成 ./docs/architecture.svg，dark 主题。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>效果：</p><p><img src="`+t+`" alt="图片" loading="lazy"></p><p><strong>常见坑和技巧</strong>：</p><p>坑一：AI 容易把所有模块堆一起，一团乱麻。跟它说“分层”，mermaid 的 <code>subgraph</code> 会帮你分组。</p><p>坑二：AI 容易把日志、监控、配置中心这些周边也画进去，主干被淹没。多说一句“周边基础设施用一个方框概括就行，别展开”。</p><p>坑三：AI 画完一张图就停，不主动迭代。第一张出来直接说“把 XX 模块展开再画一张”。<strong>迭代是常态，一次画成很少</strong>。</p><h3 id="模块依赖图" tabindex="-1">模块依赖图 <a class="header-anchor" href="#模块依赖图" aria-label="Permalink to &quot;模块依赖图&quot;">​</a></h3><p>mermaid 的 <code>graph LR</code> 或 <code>flowchart</code> 足够了。关键是<strong>让 AI 基于真实数据生成</strong>，不要编。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>看一下我的 pom.xml，画一张项目内部模块之间的依赖图。</span></span>
<span class="line"><span>外部库不画。有循环依赖用红色标出来。</span></span>
<span class="line"><span>保存成 ./docs/module-deps.svg。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>效果：</p><p><img src="`+i+`" alt="图片" loading="lazy"></p><p><strong>关键点</strong>：要求它“看 pom.xml”，说清楚让它读真实文件。不说它可能根据项目名脑补。</p><h3 id="时序图" tabindex="-1">时序图 <a class="header-anchor" href="#时序图" aria-label="Permalink to &quot;时序图&quot;">​</a></h3><p>mermaid 的 <code>sequenceDiagram</code>。画一次 API 调用的完整生命周期最顺手。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我画 POST /api/prompts/create 这个接口的调用链时序图。</span></span>
<span class="line"><span>先去 grep 真实代码，从 Controller 一路追到 DB。</span></span>
<span class="line"><span>标清楚每一步是哪个类哪个方法，保存成 ./docs/sequence-create-prompt.svg。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>效果：</p><p><img src="`+d+`" alt="图片" loading="lazy"></p><p><strong>关键点</strong>：一句“先 grep 真实代码”。不让它读代码，它就会根据接口名瞎猜调用链。</p><h3 id="数据库-schema-图" tabindex="-1">数据库 schema 图 <a class="header-anchor" href="#数据库-schema-图" aria-label="Permalink to &quot;数据库 schema 图&quot;">​</a></h3><p>mermaid 的 <code>erDiagram</code>。</p><p><strong>提示词</strong>：</p><div class="language-plain vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>看项目里的建表 SQL（db/migration 或 resources 里），画一张 ER 图。</span></span>
<span class="line"><span>主键、外键、表之间的关系标清楚。保存成 ./docs/schema.svg。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>效果：</p><p><img src="`+c+'" alt="图片" loading="lazy"></p><p><strong>关键点</strong>：让它读真实 DDL 或 JPA entity，别根据表名猜字段。</p><h2 id="让图真的好看-3-个细节" tabindex="-1">让图真的好看：3 个细节 <a class="header-anchor" href="#让图真的好看-3-个细节" aria-label="Permalink to &quot;让图真的好看：3 个细节&quot;">​</a></h2><p>画出来 vs 画得好看是两回事。好看的图是你能一直留下来的，丑的图画完一次就丢。关注 3 个细节：</p><ol><li><strong>加颜色</strong>：同类模块一个色系。核心模块用冷色（蓝、紫），周边模块用暖色（灰、琥珀），外部系统用中性色。mermaid 里用 <code>classDef</code> 定义样式，批量应用。</li><li><strong>留白</strong>：不要把每个节点都塞满字。每个方框一行标题 + 一句话描述足够，其他放到配套文档里讲。图是索引，不是百科。</li><li><strong>固定方向</strong>：架构图要么自上而下（<code>TD</code>），要么自左向右（<code>LR</code>），选一个就不要换。整个项目的所有架构图保持同一方向，你扫一眼就能对照。</li></ol><h2 id="最后一个提醒-ai-画的图一定有错" tabindex="-1">最后一个提醒：AI 画的图一定有错 <a class="header-anchor" href="#最后一个提醒-ai-画的图一定有错" aria-label="Permalink to &quot;最后一个提醒：AI 画的图一定有错&quot;">​</a></h2><p>装好工具、背熟提示词之后，你还需要守住一件事：AI 画的图一定有错。可能把一个已经废弃的模块画成核心，可能把一个重要的异步通道漏掉，可能把 3 个表的关系画反。可能把 Controller 的一个重载方法当成两个独立接口。</p><p>AI 基于它读到的代码画图，<strong>它读到的不等于全貌</strong>。老项目里那些代码之外的东西（隐性约定、历史包袱、对接方特殊需求）它看不见。</p><p>所以这一讲讲完画图能力，上一讲讲的八步心法第 8 步还要守住：<strong>AI 画初稿，你 review，修正完存到项目 <code>docs/</code> 目录</strong>。</p><p>这个修正过的图叫 <code>ARCHITECTURE.md</code> 里的那张架构图，或者项目 docs 里的那张数据流图。它是你理解这个项目的存档，下次打开项目或者新同事接手，这张图就是入门的第一份资料。图会过时，但存档过的图比脑子里的理解可靠得多。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一讲讲清楚了 5 件事。</p><ol><li><strong>讲了 SKILL 生态</strong>：Claude Code 不是出厂即定型的工具。<code>~/.claude/skills/</code> 和项目的 <code>.claude/skills/</code> 是扩展点，装一个 SKILL 就多一项能力。这一讲做消费者，11 讲做生产者。</li><li><strong>装上了画图能力</strong>：用 claude-mermaid 这套方案，Claude Code 能实时出 PNG / SVG / PDF，支持多种主题、浏览器实时预览。装法一行命令。</li><li><strong>四类图的对应场景</strong>：架构图讲系统骨架、模块依赖图讲模块关系、时序图讲调用链、ER 图讲数据结构。老项目改造里反复需要这四类，其他类型偶尔用到再说。</li><li><strong>工具策略</strong>：mermaid 为主（90% 场景），plantuml 和 drawio 兜底（复杂 UML 或精修交付图）。</li><li><strong>硬守的一条线</strong>：AI 画的图一定有错。你要 review，要修正，要存档到项目 docs 里。画图这件事不是“AI 画完就完”，是“AI 起稿 + 你把关 + 留下资产”。</li></ol><p>装好画图能力，下一讲我们真正动手，用这几类图给 Spring AI Alibaba Admin 画出完整的项目全景。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li>你现在电脑上装的 Claude Code（或其他 AI 编程工具）装过几个 SKILL / Plugin？如果装过，它们解决了你什么具体问题？如果一个也没装，是没需求，还是不知道可以装？</li><li>回想你最近接手或维护的项目，哪一类图（架构、依赖、时序、ER）你最缺？缺的原因是没画，还是画过但丢了？如果让你从零给那个项目补一张图，你会从哪一类开始？</li></ol><p>欢迎在评论区把你的答案写出来。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p><hr><h2 id="精选评论" tabindex="-1">精选评论 <a class="header-anchor" href="#精选评论" aria-label="Permalink to &quot;精选评论&quot;">​</a></h2><p><strong>康远</strong>: 我用codex，claude-mermaid mcp配置成功了，但是用相同的提示器，出来的图非常的丑，箭头非常乱，根本不是横平竖直的，基本是一个不可用的状态。。。</p><blockquote><p><strong>作者回复</strong>: 哈哈哈哈，典型问题。需要多次提示，我最近在生成一些复杂的图，会有重叠、拥挤、箭头乱的问题。</p><p>我的技巧是：在同一个会话中画图，让AI有上下文。比如我现在固定在Vs Code的CC插件里面的同一个会话画。然后画出来后告诉它哪里有问题，让他调整。然后显式让它记录下来，然后接下来效果就很好了。越画越好。</p><p>另外如果风格不满意，你直接问有哪些风格可以选。cc 会让你选的，然后选你喜欢的风格。然后接下来就是调试CC了。让它的上下文足够画出好图。</p><p>我觉得核心就是在一个对话里面反复画，养起来。</p></blockquote><hr><p><strong>朱海昆</strong>: 如果是opencode，有可以直接使用的工具吗？</p><blockquote><p><strong>作者回复</strong>: 这个我还真没研究下诶，skill理论上是通用的，可以问下cc</p></blockquote><hr><p><strong>holyman</strong>: 画出的图是 mermaid 原生的效果，没有你提供的图好看， 你提供的图是加了特殊的提示词或者其他skill吗？</p><blockquote><p><strong>作者回复</strong>: 我准备加一个如何画好图的补充章节，好多人问这个问题，等我写一下～。老歌🌹</p></blockquote><hr><p><strong>秋晨</strong>: 课程中推荐的claude-mermaid，虽然能够安装，但是无法连接MCP服务，可能跟插件的环境兼容性有关系。 但其画图的核心是mermaid-cli，于是退而求其次选择使用mermaid-cli，但是同样的提示词画出的图的效果远不如课程中示例效果。 老师是否可以在本课程中提供完整的提示词？否则就会陷入买家秀和卖家秀的困境</p><blockquote><p><strong>作者回复</strong>: 我现在给出来的就是我用的提示词。你加一下群，我们讨论下这个问题。有可能有两个原因：</p><ol><li>风格需要再提示下</li><li>cc 不知道你喜欢哪个风格，就随机画了一种。</li></ol></blockquote><hr><p><strong>时间小鱼</strong>: Error: ERROR: Failed to set up chrome v148.0.7778.97! Set &quot;PUPPETEER_SKIP_DOWNLOAD&quot; env variable to skip download.</p><blockquote><p><strong>作者回复</strong>: 看起来是不是没翻墙，有些工具被墙了，比如github。可以看看是不是这个原因</p></blockquote><hr><p><strong>百炼钢</strong>: 解决画图的问题了； 我在 CSDN gitcode 上下载了一个 mcp-mermaid ，然后用 ccswitch 配置一下，可以画图了；</p><p><a href="https://gitcode.com/gh_mirrors/mc/mcp-mermaid" target="_blank" rel="noreferrer">https://gitcode.com/gh_mirrors/mc/mcp-mermaid</a></p><blockquote><p><strong>作者回复</strong>: 厉害👍👍，可能有一些需要墙的问题，每个人的网络环境不一样。</p></blockquote><hr><p><strong>Q:-_-</strong>: 请问画图那块是完整的提示词吗</p><blockquote><p><strong>作者回复</strong>: 是的，都是完整的提示词。如果画出来的效果不好，可以反复提示下。也可以参考其他的回复～🌹</p></blockquote><hr><p><strong>浩仔是程序员</strong>: 为啥老师你展示的图那么好看</p><blockquote><p><strong>作者回复</strong>: 我会提示cc 我想要什么样子的风格的图。你可以把我的图截图给cc，告诉cc，我就是要这个风格图。以后按照这个风格生成，应该就可以了</p></blockquote><hr><p><strong>MarkusZhang</strong>: npm install -g claude-mermaid 执行安装不了，是有什么特殊原因吗？</p><blockquote><p><strong>作者回复</strong>: 我自己用这个命令能成功。有什么报错吗？发出来一起看下。</p></blockquote><hr><p><strong>王巍</strong>: 用的模型是官方模型，还是国产模型</p><blockquote><p><strong>作者回复</strong>: 我用的是Claude Code的官方模型</p></blockquote><hr><p><strong>不矫情不做作那是我</strong>: 有一个问题，就是我不懂java 代码，这种情况下我怎么知道画的图有没有问题呢</p><blockquote><p><strong>作者回复</strong>: 好问题，你可以往下看，看后面的内容。</p></blockquote><hr><p><strong>西蒙</strong>: 老师，最好的是建立个微信群，可以交流一下，很多操作不出来，找不到问题。</p><blockquote><p><strong>作者回复</strong>: 准备建立了哈~ 感谢提醒</p></blockquote><hr><p><strong>西蒙</strong>: graph LR A[用户] --&gt; B[输入账号密码] B --&gt; C{验证} C --&gt;|成功| D[登录成功] C --&gt;|失败| E[登录失败] 可以生成这样的文件，但是在VS code里面看不到图，已经安装了插件Mermaid Viewer</p><blockquote><p><strong>作者回复</strong>: 稍后会创建个微信群，在微信群沟通哈~~</p></blockquote><hr><p><strong>百炼钢</strong>: 安装不了 plugin ，是否需要订阅claude + 梯子 ？</p><blockquote><p><strong>作者回复</strong>: 是什么错误呢？可以发出来看看</p></blockquote>',135)])])}const q=a(g,[["render",u]]);export{v as __pageData,q as default};
